package com.bank.profile.consumer;

import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Component;
import lombok.extern.slf4j.Slf4j;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Component
@Slf4j
public class ProfileCacheConsumer {

    // Local materialized view rebuilt by replaying the compacted topic.
    private final Map<String, String> profileCache = new ConcurrentHashMap<>();

    @KafkaListener(topics = "account.profiles", groupId = "profile-cache")
    public void onRecord(org.apache.kafka.clients.consumer.ConsumerRecord<String, String> rec) {
        String accountId = rec.key();
        String value = rec.value();
        if (value == null) {
            // TOMBSTONE: the key was deleted. Remove it from the local view.
            profileCache.remove(accountId);
            log.info("Tombstone applied, evicted profile for {}", accountId);
        } else {
            profileCache.put(accountId, value);
            log.info("Upserted profile for {}", accountId);
        }
    }

    public String getProfile(String accountId) { return profileCache.get(accountId); }
}
