// ─── File: demo/TombstoneDemo.java ───
package com.bank.profile.demo;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TombstoneDemo {

    private static final Logger log = Logger.getLogger(TombstoneDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        CompactedLog logTopic = new CompactedLog();

        // Three versions of SAV2001 land in the first (now closed) segment.
        logTopic.append("SAV2001", "profile-v1");
        logTopic.append("SAV2001", "profile-v2");
        logTopic.append("CUR3001", "priya-v1");
        logTopic.append("SAV2001", "profile-v3");
        logTopic.rollSegment(); // close that segment; a new active segment begins

        // Compliance deletes SAV2001: a tombstone in the ACTIVE segment.
        logTopic.append("SAV2001", null);

        log.info("=== Read IMMEDIATELY after tombstone (before cleaning) ===");
        for (Record r : logTopic.readAll()) {
            log.info("offset=" + r.offset + " key=" + r.key + " value=" + r.value);
        }
        log.warning("Old SAV2001 versions still visible: cleaner has not run on closed segments yet");

        log.info("=== Run the log cleaner (compaction pass) ===");
        new LogCleaner().compact(logTopic, log);

        log.info("=== Read AFTER cleaning ===");
        for (Record r : logTopic.readAll()) {
            log.info("offset=" + r.offset + " key=" + r.key + " value=" + r.value);
        }

        log.info("=== Consumer view WITH correct tombstone handling ===");
        ProfileCacheConsumer good = new ProfileCacheConsumer(true);
        for (Record r : logTopic.readAll()) good.apply(r);
        log.info("SAV2001 in cache? " + (good.get("SAV2001") != null) + " (should be false)");

        log.info("=== Consumer view IGNORING tombstones (the bug) ===");
        ProfileCacheConsumer bad = new ProfileCacheConsumer(false);
        for (Record r : logTopic.readAll()) bad.apply(r);
        log.severe("SAV2001 still cached? " + (bad.get("SAV2001") != null)
                + " (stale because nulls were ignored)");
    }
}

// ─── Would be in Record.java in a real project ───
class Record {
    final long offset; final String key; final String value;
    Record(long offset, String key, String value) { this.offset = offset; this.key = key; this.value = value; }
}

// ─── Would be in LogSegment.java in a real project ───
class LogSegment {
    final List<Record> records = new ArrayList<>();
    boolean closed = false;
}

// ─── Would be in CompactedLog.java in a real project ───
class CompactedLog {
    private final List<LogSegment> segments = new ArrayList<>();
    private long nextOffset = 0;

    CompactedLog() { segments.add(new LogSegment()); }

    void append(String key, String value) {
        active().records.add(new Record(nextOffset++, key, value));
    }

    void rollSegment() { active().closed = true; segments.add(new LogSegment()); }

    LogSegment active() { return segments.get(segments.size() - 1); }
    List<LogSegment> segments() { return segments; }

    List<Record> readAll() {
        List<Record> all = new ArrayList<>();
        for (LogSegment s : segments) all.addAll(s.records);
        return all;
    }
}

// ─── Would be in LogCleaner.java in a real project ───
class LogCleaner {
    // Compact ONLY closed segments. The active segment is never touched.
    void compact(CompactedLog logTopic, Logger log) {
        Map<String, Record> latest = new LinkedHashMap<>();
        List<LogSegment> closed = logTopic.segments().stream()
                .filter(s -> s.closed).toList();
        for (LogSegment s : closed) {
            for (Record r : s.records) latest.put(r.key, r); // keep newest per key
        }
        // Rewrite closed segments keeping only the surviving records per key.
        for (LogSegment s : closed) {
            s.records.removeIf(r -> latest.get(r.key) != r);
        }
        log.info("Compaction kept latest-per-key in closed segments; "
                + "tombstone for SAV2001 remains in active segment (held " 
                + "delete.retention.ms before removal)");
    }
}

// ─── Would be in ProfileCacheConsumer.java (demo copy) ───
class ProfileCacheConsumer {
    private final boolean handleTombstones;
    private final Map<String, String> cache = new LinkedHashMap<>();
    ProfileCacheConsumer(boolean handleTombstones) { this.handleTombstones = handleTombstones; }

    void apply(Record r) {
        if (r.value == null) {
            if (handleTombstones) cache.remove(r.key); // correct
            // else: bug — ignore the delete, keep stale value
        } else {
            cache.put(r.key, r.value);
        }
    }
    String get(String key) { return cache.get(key); }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("[%1$tF %1$tT] [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
